///! Comptime scalar function: ct_add_numbers(a BIGINT, b BIGINT) -> BIGINT
///!
///! Equivalent to zig_add_numbers, but registration and the vectorized callback
///! are generated by the comptime scalar framework. The per-row logic is a
///! one-line function; the framework handles vectorized dispatch, NULL
///! propagation, and type registration.
const comptime_scalar = @import("../lib/comptime_scalar.zig");
const db = @import("../lib/duckdb.zig");

/// Per-row implementation: add two 64-bit integers.
fn add(a: i64, b: i64) i64 {
    return a + b;
}

/// Comptime-generated scalar function type.
const CtAddNumbers = comptime_scalar.Function("ct_add_numbers", add);

/// Register the ct_add_numbers scalar function with DuckDB.
pub fn register(connection: db.Connection) !void {
    return CtAddNumbers.register(connection);
}
